ct.medium_create_time as createTime,ct.col_type as colType,t.task_main_id as originalTaskRecordId,dt.device_name as uavName,ct.longitude ,ct.latitude , ct.height as altitude ,lt.flight_route_name,ct.watermark_url as watermarkUrl,ct.is_watermark as isWatermark,ct.remark as remark,
ct.road_info,t.start_nest_code,t.end_nest_code
FROM vm_air_line_col_t ct
left join vm_air_task_t t on t.plan_task_id = ct.taskrecord_id
left join vm_air_line_t lt on lt.flight_route_id = t.flight_route_id
left join vm_uav_device_info_t dt on dt.device_code = t.uav_code COLLATE utf8mb4_general_ci
WHERE ct.user_id = #{userId} and ct.col_type = #{dataType}

    and medium_create_time >= #{createStartTime} and medium_create_time <= #{createEndTime}


    and collect_name like concat('%',#{queryName},'%')


