SELECT t.plan_task_id taskRecordId, t.reality_time as startTime, t.access_node as accessNode, lt.flight_route_name as airLineName, CASE WHEN lt.flight_main_type = 1 THEN CONCAT('指点飞行', DATE_FORMAT(t.reality_time, '%Y%m%d%H%i')) WHEN lt.flight_main_type = 2 THEN CONCAT('一键起飞', DATE_FORMAT(t.reality_time, '%Y%m%d%H%i')) ELSE CONCAT(lt.flight_route_name, DATE_FORMAT(t.reality_time, '%Y%m%d%H%i')) END as taskName FROM vm_air_task_t t LEFT JOIN vm_air_line_t lt ON lt.flight_route_id = t.flight_route_id
AND lt.device_Code = #{deviceCode}
WHERE t.delete_flag = 0 AND t.task_status = 1 and t.flight_route_id is not null and t.reality_time is not null ${dataScope} ORDER BY t.plan_time DESC

select photo_url as photoUrl,photo_id as photoId,time_created as timeCreated,photo_json_info as photoJsonInfo,
photo_height as photoHeight,uav_name as uavName,longitude,latitude,point_type as pointType,task_record_id as taskRecordId,task_Record_Name as taskRecordName,point_name as name
from vm_air_map_point_t t
where id = #{id} and delete_flag = 0

    AND device_code = #{deviceCode}


    AND task_record_id = #{taskRecordId}


    and DATE_FORMAT(time_created,'%Y-%m-%d %H:%i:%s') >= #{timeCreatedStartTime}
    and DATE_FORMAT(time_created,'%Y-%m-%d %H:%i:%s') <= #{timeCreatedEndTime}


    AND st_distance_sphere(POINT(longitude, latitude), POINT(#{longitude}, #{latitude}))  <= 3.0

${dataScope}

